native.lab_translations:
import QtQuick
import qs.Commons

// Native strings use the shell catalog. Standalone packaging supplies the
// same interface over its bundled plugin catalogs.
QtObject {
  readonly property string language: I18n.language
  function t(key, fallback) { return I18n.t(key, fallback) }
}

standalone.write_desktop:
write_desktop() {
  local executable="$LAB_ROOT/bin/omarchy-labctl"
  executable=${executable//\\/\\\\\\\\}
  executable=${executable//\"/\\\"}
  executable=${executable//\$/\\\$}
  executable=${executable//\`/\\\`}
  executable=${executable//%/%%}
  mkdir -p "$(dirname "$DESKTOP_FILE")"
  cat >"$DESKTOP_FILE" <<EOF
[Desktop Entry]
Name=Omarchy Lab
Comment=Disposable Omarchy KVM for development and PoCs
Exec="$executable" launch
Icon=omarchy
Terminal=false
Type=Application
Categories=System;Emulator;
EOF
  update-desktop-database "$(dirname "$DESKTOP_FILE")" 2>/dev/null || true
}

standalone.lab_translations:
import QtQuick
import qs.Commons as Commons

// Standalone catalogs follow the shell language and fall back to English.
Commons.Translations {
  directory: Qt.resolvedUrl("default/lab-vm")
}
